/**
 * Sub packs (Daily Teaching System, Parts 3 and 5): /<locale>/sub-plans/<slug>.
 *
 * One school day of review for one grade, for the day the teacher is away: a worksheet for every block, a script for
 * the guest teacher, forms. The page renders one generated file per language:
 *
 *   content/sub-plans/packs.<loc>.json   GENERATED by scripts/sub-plans/assemble.js
 *   content/sub-plans/ui.<loc>.json      the page's and the guest teacher pages' own strings
 *
 * status 'pilot' = noindex, in no sitemap, linked from nowhere.
 */
import { pagePdf } from '@/lib/units';

export interface SubBlock {
  key: string;
  minutes: number;
  point: string;
  type: string;
  title: string;
  instruction: string;
  core: string;
  hard?: string;
  easy?: string;
  script: { say: string; first: string; stuck: string };
}
export interface SubPack {
  id: string;
  slug: string;
  status: 'pilot' | 'live';
  grade: string;
  /** 'week': a day for one week of the grade's plans (Part 5.4), with its `week` */
  position: 'early' | 'middle' | 'late' | 'week';
  week?: number;
  title: string;
  metaTitle: string;
  metaDescription: string;
  minutes: number;
  blocks: SubBlock[];
}
export type SubUi = Record<string, string>;

const cache = new Map<string, unknown>();
async function load<T>(key: string, importer: () => Promise<{ default: unknown }>): Promise<T | null> {
  if (cache.has(key)) return cache.get(key) as T;
  try {
    const mod = await importer();
    cache.set(key, mod.default);
    return mod.default as T;
  } catch {
    cache.set(key, null);
    return null;
  }
}
export async function getSubPacks(locale: string): Promise<SubPack[]> {
  const f = await load<{ packs: SubPack[] }>(`packs.${locale}`, () => import(`@/content/sub-plans/packs.${locale}.json`));
  return f?.packs ?? [];
}
export const getSubUi = (locale: string) => load<SubUi>(`ui.${locale}`, () => import(`@/content/sub-plans/ui.${locale}.json`));
export async function getSubPack(locale: string, slug: string): Promise<SubPack | null> {
  return (await getSubPacks(locale)).find((p) => p.slug === slug) ?? null;
}
export async function subPackSiblings(id: string, locales: readonly string[]): Promise<Record<string, string>> {
  const out: Record<string, string> = {};
  for (const l of locales) {
    const p = (await getSubPacks(l)).find((x) => x.id === id && x.status === 'live');
    if (p) out[l] = p.slug;
  }
  return out;
}

/** every worksheet of the pack in the order of the day: for everyone, easier, for early finishers */
export function subPackPdfList(locale: string, pack: SubPack): string[] {
  const out: string[] = [];
  for (const b of pack.blocks) { out.push(b.core); if (b.easy) out.push(b.easy); if (b.hard) out.push(b.hard); }
  return [...new Set(out)].map((slug) => pagePdf(locale, slug).replace(/^https?:\/\/[^/]+/, ''));
}
/** the Teacher-only file of a pack, as the gate knows it (lib/teacher-files.ts) */
export const subPackScriptFile = (pack: SubPack) => `sub-plans/${pack.id}/guest-teacher-pages`;

/** times of the year in the order of the year, for every list of packs */
export const POSITION_ORDER = ['early', 'middle', 'late'] as const;

/**
 * What the hub of a language lists. Live packs when there are any; a language whose packs are all pilots shows its
 * pilots on a noindex hub (that is how a new language is read before it is published); no packs = no hub (404).
 * The days of the year only: the week days (Part 5.4) are listed apart (listedWeekPacks), are noindex and in no
 * sitemap, so that this list (the hub's, the sitemap's, every count of sub plans) stays the search face.
 */
export async function listedSubPacks(locale: string): Promise<{ live: boolean; packs: SubPack[] }> {
  const packs = (await getSubPacks(locale)).filter((p) => p.position !== 'week');
  const livePacks = packs.filter((p) => p.status === 'live');
  if (livePacks.length) return { live: true, packs: livePacks };
  return { live: false, packs };
}

/** the week days of a language that pages show: live ones only (a pilot week day is shown nowhere), by grade and week */
export async function listedWeekPacks(locale: string): Promise<SubPack[]> {
  return (await getSubPacks(locale)).filter((p) => p.position === 'week' && p.status === 'live').sort((a, b) => (a.week ?? 0) - (b.week ?? 0));
}
/** the live week day before and after a week day in its grade (a pilot is linked from nowhere) */
export async function weekNeighbours(locale: string, pack: SubPack): Promise<{ prev: SubPack | null; next: SubPack | null }> {
  const all = (await getSubPacks(locale)).filter((p) => p.position === 'week' && p.grade === pack.grade && p.status === 'live');
  return { prev: all.find((p) => p.week === (pack.week ?? 0) - 1) ?? null, next: all.find((p) => p.week === (pack.week ?? 0) + 1) ?? null };
}
const BINDER_GRADE_ID: Record<string, string> = { P: 'p', K: 'k', '1': 'g1', '2': 'g2', '3': 'g3', '4': 'g4', '5': 'g5' };
/** the Teacher-only sub binder pages of a grade (Part 5.4, scripts/sub-plans/build-pack.js) */
export const subBinderFile = (grade: string) => `sub-plans/binder-${BINDER_GRADE_ID[grade] ?? grade.toLowerCase()}/sub-binder-pages`;
